   AND ISNULL(TRY_CONVERT(INT,SESSION_CONTEXT(N'AllowDatabaseReset')),0)<>1
    THROW 51300,N'CSDL đã có dữ liệu. Dùng migration; reset cần AllowDatabaseReset=1.',1;
