-- =========================================================================
-- 3. THỦ TỤC SINH DỮ LIỆU TẢI LỚN ĐỂ KIỂM THỬ HIỆU NĂNG & CHỤP ẢNH EXECUTION PLAN
-- Nghiệp vụ: Phục vụ đo đạc chênh lệch hiệu năng trước và sau khi đánh 5 Index (Bước 6)
-- Kỹ thuật: Sinh hàng loạt N đơn hàng ngẫu nhiên với giao dịch theo lô (Batch Transaction)
-- =========================================================================
CREATE OR ALTER PROCEDURE dbo.sp_SinhDuLieuMau_TestTai @SoLuongDonHang INT=5000 AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 IF DB_NAME() NOT LIKE 'DBMSTest[_]%' AND DB_NAME() NOT LIKE '%[_]Benchmark'
  THROW 51301,N'Chỉ sinh tải trong CSDL DBMSTest_* hoặc *_Benchmark riêng biệt.',1;
 IF @SoLuongDonHang IS NULL OR @SoLuongDonHang<1 OR @SoLuongDonHang>100000
  THROW 51302,N'Số đơn phải trong 1..100000.',1;
 BEGIN TRY
  BEGIN TRANSACTION;
  -- Controlled replenishment in this disposable fixture; never disable production triggers.
  UPDATE dbo.TonKho SET SoLuongTon=SoLuongTon+@SoLuongDonHang*3;
  DECLARE @i INT=1,@Id INT,@KH INT,@SP INT,@Qty INT,@Price DECIMAL(12,2),@State INT,@Discount DECIMAL(5,4);
  WHILE @i<=@SoLuongDonHang
  BEGIN
   SELECT @KH=(@i%2)+1,@SP=(@i%4)+1,@Qty=(@i%3)+1,@State=@i%4;
   SELECT @Price=GiaBanHienTai FROM dbo.SanPham WHERE MaSP=@SP AND DaXoa=0;
   SELECT @Discount=CASE LoaiKH WHEN 1 THEN 0.10 WHEN 2 THEN 0.15 ELSE 0 END FROM dbo.KhachHang WHERE MaKH=@KH;
   INSERT dbo.DonHang(MaKH,MaNV,MaKhoXuat,NgayDat,TiLeChietKhau)
    VALUES(@KH,2,(@i%2)+1,DATEADD(MINUTE,-@i*7,GETDATE()),@Discount);
   SET @Id=SCOPE_IDENTITY();
   INSERT dbo.ChiTietDonHang(MaDH,MaSP,SoLuong,DonGiaBan) VALUES(@Id,@SP,@Qty,@Price);
   IF @State>=1 UPDATE dbo.DonHang SET TrangThai=1 WHERE MaDH=@Id;
   IF @State>=2 UPDATE dbo.DonHang SET TrangThai=2 WHERE MaDH=@Id;
   IF @State>=3 UPDATE dbo.DonHang SET TrangThai=3 WHERE MaDH=@Id;
   SET @i+=1;
  END;
  COMMIT; SELECT @SoLuongDonHang AS GeneratedOrders;
 END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; THROW; END CATCH;
END;

GO

PRINT N'=========================================================================';
PRINT N'ĐÃ NẠP DỮ LIỆU MẪU KIỂM THỬ THÀNH CÔNG CHO TOÀN BỘ 11 BẢNG!';
PRINT N'=========================================================================';
GO

